--
-- Table structure for table `fees`
--

DROP TABLE IF EXISTS `fees`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fees` (
  `id` varchar(36) NOT NULL,
  `category_id` varchar(36) NOT NULL,
  `class_id` varchar(36) NOT NULL,
  `school_id` varchar(36) DEFAULT NULL,
  `garrison_id` varchar(36) DEFAULT NULL,
  `academic_year_id` varchar(36) DEFAULT NULL,
  `fee_type` enum('registration','admission','tuition','exam','other') NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `description` text,
  `effective_date` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `category_id` (`category_id`),
  KEY `class_id` (`class_id`),
  KEY `school_id` (`school_id`),
  KEY `garrison_id` (`garrison_id`),
  KEY `academic_year_id` (`academic_year_id`),
  CONSTRAINT `fees_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`),
  CONSTRAINT `fees_ibfk_2` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`),
  CONSTRAINT `fees_ibfk_3` FOREIGN KEY (`school_id`) REFERENCES `schools` (`id`),
  CONSTRAINT `fees_ibfk_4` FOREIGN KEY (`garrison_id`) REFERENCES `garrisons` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fees_ibfk_5` FOREIGN KEY (`academic_year_id`) REFERENCES `academic_years` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

