CREATE TABLE `receipts` (
  `id` varchar(36) NOT NULL,
  `student_id` varchar(36) DEFAULT NULL,
  `payment_id` varchar(36) DEFAULT NULL,
  `school_id` varchar(36) DEFAULT NULL,
  `garrison_id` varchar(36) DEFAULT NULL,
  `class_id` varchar(36) DEFAULT NULL,
  `registration_id` varchar(36) DEFAULT NULL,
  `issued_by` varchar(36) DEFAULT NULL,
  `receipt_type` varchar(100) DEFAULT NULL,
  `amount` decimal(10,2) DEFAULT NULL,
  `date_issued` date DEFAULT NULL,
  `venue` varchar(100) DEFAULT NULL,
  `logo_url` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `assessment_id` varchar(36) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `school_id` (`school_id`),
  KEY `garrison_id` (`garrison_id`),
  KEY `fk_receipts_exam` (`assessment_id`),
