  `subject_id` varchar(36) DEFAULT NULL,
  `term_id` varchar(36) DEFAULT NULL,
  `ca_score` decimal(5,2) DEFAULT '0.00',
  `exam_score` decimal(5,2) DEFAULT '0.00',
  `total_score` decimal(5,2) DEFAULT '0.00',
  `grade` varchar(5) DEFAULT NULL,
